  requires (len(xs) >= 0)
  ensures (result >= max_so_far)
  effects pure
  example (max_subarray_aux([], 3, 5) == 5)
  example (max_subarray_aux([-1, 2], 3, 5) == 5)
{
  match xs { [] => max_so_far [h, ..t] => if (h >= (max_ending_here + h)) then if (max_so_far >= h) then max_subarray_aux(t, h, max_so_far) else max_subarray_aux(t, h, h) else if (max_so_far >= (max_ending_here + h)) then max_subarray_aux(t, (max_ending_here + h), max_so_far) else max_subarray_aux(t, (max_ending_here + h), (max_ending_here + h)) }
}

fn head(xs: List[Int]) -> Int
  requires (len(xs) >= 1)
  ensures contains(xs, result)
  effects pure
  example (head([5, 6, 7]) == 5)
  example (head([9]) == 9)
{
  match xs { [] => 0 [h, ..t] => h }
}

fn start_sum_le(xs: List[Int], bound: Int) -> Bool
  requires (len(xs) >= 1)
  ensures ((not result) or (head(xs) <= bound))
  effects pure
  example (start_sum_le([1, -2, 3, 4, -1], 7) == true)
  example (start_sum_le([4, -1], 4) == true)
  example (start_sum_le([4, -1], 3) == false)
{
  match xs { [] => true [h, ..t] => match t { [] => (h <= bound) [_, .._] => ((h <= bound) and start_sum_le(t, (bound - h))) } }
}

fn start_sum_eq(xs: List[Int], target: Int) -> Bool
  requires (len(xs) >= 1)
  ensures ((not (result and (len(xs) == 1))) or (head(xs) == target))
  effects pure
