fn max(xs: List[Int]) -> Int
  requires (len(xs) >= 1)
  ensures contains(xs, result)
  ensures forall x in xs: (x <= result)
  effects pure
  example (max([3, 9, 1]) == 9)
  example (max([5]) == 5)
  example (max([1, 2]) == 2)
{
  match xs { [] => 0 [h, ..t] => match t { [] => h [h2, ..t2] => if (h >= max(t)) then h else max(t) } }
}

fn max_excluding_opt(xs: List[Int], to_exclude: Int) -> Option[Int]
  requires distinct(xs)
  ensures match result { None => true Some(v) => ((contains(xs, v) and (v != to_exclude)) and (forall x in xs: ((x == to_exclude) or (x <= v)))) }
  effects pure
  example (max_excluding_opt([3, 9, 1], 9) == Some(3))
  example (max_excluding_opt([5], 5) == None)
  example (max_excluding_opt([], 5) == None)
{
  match xs { [] => None [h, ..t] => if (h == to_exclude) then max_excluding_opt(t, to_exclude) else match max_excluding_opt(t, to_exclude) { None => Some(h) Some(v) => if (h >= v) then Some(h) else Some(v) } }
}

fn second_largest(xs: List[Int]) -> Option[Int]
  requires distinct(xs)
  ensures ((len(xs) >= 2) or (result == None))
  ensures ((len(xs) < 2) or (match result { None => false Some(v) => ((contains(xs, v) and (v != max(xs))) and (forall x in xs: ((x == max(xs)) or (x <= v)))) }))
  effects pure
  example (second_largest([3, 9, 1]) == Some(3))
  example (second_largest([4]) == None)
  example (second_largest([]) == None)
{
  match xs { [] => None [_, ..t] => match t { [] => None _ => max_excluding_opt(xs, max(xs)) } }
}

